  const getLanguage = () => {
    const requested = new URLSearchParams(location.search).get("lang");
    if (supported.includes(requested)) { localStorage.setItem("wc_language", requested); history.replaceState(null, "", location.pathname + location.hash); return requested; }
    const stored = localStorage.getItem("wc_language");
    if (supported.includes(stored)) return stored;
    const detected = (navigator.languages || [navigator.language])
      .map((value) => String(value || "").toLowerCase().split("-")[0])
      .find((value) => supported.includes(value));
    return detected || "fr";
  };
