    document.documentElement.lang = language;
    document.documentElement.dir = language === "ar" ? "rtl" : "ltr";
    document.querySelectorAll("[data-i18n]").forEach(node => { node.textContent = t(node.dataset.i18n, language); });
    document.querySelectorAll("[data-i18n-placeholder]").forEach(node => { node.placeholder = t(node.dataset.i18nPlaceholder, language); });
    document.querySelectorAll("[data-i18n-aria]").forEach(node => { node.setAttribute("aria-label", t(node.dataset.i18nAria, language)); });
    document.querySelectorAll("[data-language]").forEach(select => { select.value = language; });
    const titleKey = document.body?.dataset.titleKey;
    if (titleKey) document.title = `${t(titleKey, language)} | Workcrute`;
